3. Helpers after `rosetaInvocations`:
```dart
/// Jobs in the workflow whose run-steps invoke `arch -x86_64 dart`,
/// derived from the per-line [rosetaInvocations] helper. The AC2 group
/// must NOT scan whole multi-line scripts with [rosetaCommand]: `^`
/// without `multiLine:` only matches at string start, so comment-first
/// scripts (every script in this repo) were invisible and the group
/// registered zero tests (gh-2409 review thread 1).
Set<String> rosetaDartJobs(String workflowPath) =>
   rosetaInvocations(workflowPath)
       .where((inv) => inv.$3 == 'dart')
       .map((inv) => inv.$1)
       .toSet();

/// True when any top-level job step is a dart-lang/setup-dart use carrying
/// an explicit `architecture:` pin — the pairing AC2 requires for the
/// bare-`dart` exemption in AC1.
bool hasSetupDartArchPin(YamlList steps) => steps
   .whereType<YamlMap>()
   .any(
     (s) =>
         s['uses']?.toString().startsWith('dart-lang/setup-dart') == true &&
         (s['with'] as YamlMap?)?.containsKey('architecture') == true,
   );

/// AC1's safety rule for a Rosetta target: an absolute path (the caller
/// took responsibility for a universal binary) or the bare `dart`
/// (exact-arch SDK via setup-dart — AC2 keeps that pairing honest).
bool isSafeRosettaTarget(String cmd) =>
   cmd.startsWith('/') || archExactSdkCommands.contains(cmd);
``

